export const LIVE_LOCALES: readonly Locale[] = LOCALES.filter(locale => Object.hasOwn(ARTICLE_SLUGS, locale.code));
export function localesWith(slug: string): readonly Locale[] { return LIVE_LOCALES.filter(locale => ARTICLE_SLUGS[locale.code].includes(slug)); }
